  el.dispatchEvent(new Event('change',{bubbles:true}));
}
async function fetchXHR(){
  window.__lastXHR = null;
  return new Promise(async (resolve)=>{
    let waited=0;
    const check = async ()=>{
      if(window.__lastXHR || waited>=6000){ resolve(window.__lastXHR); return; }
      waited+=200; await new Promise(r=>setTimeout(r,200)); check();
    };
    check();
  });
}

const ranges = [
  ['2024-08-24','2024-11-24'],
  ['2024-11-24','2025-02-24'],
  ['2025-02-24','2025-05-24'],
