  el.dispatchEvent(new Event('change',{bubbles:true}));
}
async function waitXHR(){
  let waited=0;
  while(!window.__lastXHR && waited<6000){ await new Promise(r=>setTimeout(r,150)); waited+=150; }
  return window.__lastXHR;
}
async function runQuarter(s,e){
  setInputByName('StartInvDate', s);
  setInputByName('EndInvDate', e);
  window.__lastXHR = null;
