window.waitXHR = async function(){
  let waited=0;
  while(!window.__lastXHR && waited<6000){ await new Promise(r=>setTimeout(r,150)); waited+=150; }
  return window.__lastXHR;
};
window.runQuarter = async function(s,e){
  window.setSelect('SearchItem','MerID');
  window.setQueryText('337391376');
  window.setInputByName('StartInvDate', s);
  window.setInputByName('EndInvDate', e);
  window.__lastXHR = null;
  search_invoice_info.send_search_invoice('1');
  let raw = await window.waitXHR();
  let d = JSON.parse(raw);
  window.__allRows.push(...d.result.InvoiceData);
  const totalPages = d.result.Page;
  for (let p=2; p<=totalPages; p++){
    window.__lastXHR = null;
    search_invoice_info.send_search_invoice(String(p));
    raw = await window.waitXHR();
    d = JSON.parse(raw);
    window.__allRows.push(...d.result.InvoiceData);
  }
  return {range:[s,e], pages: totalPages, total: window.__allRows.length};
};
