window.runQuarter = async function(s,e){
  window.setSelect('SearchItem','MerID');
  window.setQueryText('337391376');
  window.setInputByName('StartInvDate', s);
  window.setInputByName('EndInvDate', e);
  window.__lastXHR = null;
  search_invoice_info.send_search_invoice('1');
  let raw = await window.waitXHR();
  let d = JSON.parse(raw);
  if (d.result && d.result.InvoiceData) {
    window.__allRows.push(...d.result.InvoiceData);
    const totalPages = d.result.Page;
    for (let p=2; p<=totalPages; p++){
      window.__lastXHR = null;
      search_invoice_info.send_search_invoice(String(p));
      raw = await window.waitXHR();
      d = JSON.parse(raw);
      window.__allRows.push(...d.result.InvoiceData);
    }
  }
  return {range:[s,e], total: window.__allRows.length};
};
await window.runQuarter('2026-01-01','2026-03-24');

const seen = new Set();
const dedup = [];
for (const row of window.__allRows) {
  const key = row.II_Invoice_Number + '|' + row.II_Mer_Order_Num;
  if (!seen.has(key)) { seen.add(key); dedup.push(row); }
}
const parseAmt = s => parseInt((s||'0').toString().replace(/,/g,''),10);
const voided = dedup.filter(r=>r.II_Invoice_Status==='2');
const valid = dedup.filter(r=>r.II_Invoice_Status!=='2');
({
  dedupCount: dedup.length,
  voidedCount: voided.length,
  voidedTotal: voided.reduce((s,r)=>s+parseAmt(r.II_Total_Amt),0),
  validCount: valid.length,
  validTotal: valid.reduce((s,r)=>s+parseAmt(r.II_Total_Amt),0),
  b2bTotal: valid.filter(r=>r.II_Category==='B2B').reduce((s,r)=>s+parseAmt(r.II_Total_Amt),0),
  b2cTotal: valid.filter(r=>r.II_Category==='B2C').reduce((s,r)=>s+parseAmt(r.II_Total_Amt),0),
});
